// agent-ledger plugin for OpenCode, V1 (1.x) and V2 (2.x). agent-ledger-plugin:v2
// Generated by `agent-ledger init --agent opencode`. Do not edit: re-run init instead.
//
// Both versions load .opencode/plugins/*.js. This file has exactly one default export:
//   - OpenCode V1 calls server(input) and uses the returned hooks (setup is ignored);
//   - OpenCode V2 calls setup(ctx) and registers hooks on ctx (server is ignored).
//
// Every tool call is sent to agent-ledger before it runs. "deny" throws, so the tool never runs and
// the model sees the reason. "ask": V2 opens OpenCode's own approval prompt (ctx.permission.assert);
// V1 plugins cannot prompt, so there it blocks with a "needs human approval" message. Results,
// failures, prompts and session start/stop are recorded too. Recording never throws.
import { spawn } from "node:child_process"

const HOOK = __HOOK_ARGV__
const FAIL_CLOSED = __FAIL_CLOSED__
const TIMEOUT_MS = 10000

function call(payload) {
  return new Promise((resolve) => {
    let child
    try {
      child = spawn(HOOK[0], HOOK.slice(1), { stdio: ["pipe", "pipe", "pipe"] })
    } catch (e) {
      resolve({ failed: `cannot start agent-ledger: ${e.message}` })
      return
    }
    let out = ""
    let err = ""
    let done = false
    const finish = (value) => {
      if (!done) {
        done = true
        clearTimeout(timer)
        resolve(value)
      }
    }
    const timer = setTimeout(() => {
      child.kill("SIGKILL")
      finish({ failed: "agent-ledger timed out" })
    }, TIMEOUT_MS)
    child.stdout.on("data", (d) => (out += d))
    child.stderr.on("data", (d) => (err += d))
    child.on("error", (e) => finish({ failed: `cannot start agent-ledger: ${e.message}` }))
    child.on("close", (code) => {
      if (code === 2) return finish({ failed: err.trim() || "agent-ledger failed (fail-closed)", closed: true })
      if (!out.trim()) return finish({})
      try {
        finish(JSON.parse(out))
      } catch {
        finish({ failed: "agent-ledger returned invalid output" })
      }
    })
    child.stdin.on("error", () => {})
    child.stdin.end(JSON.stringify(payload))
  })
}

async function record(payload) {
  try {
    await call(payload)
  } catch {
    // recording must never break the session
  }
}

// Shared decision logic. `askUser` returns true if a person approved, false otherwise (V1: always false).
async function gate(payload, askUser) {
  const res = await call(payload)
  if (res.failed) {
    if (FAIL_CLOSED || res.closed) throw new Error(`agent-ledger: ${res.failed}`)
    return
  }
  if (res.decision === "deny") throw new Error(res.reason || "agent-ledger: blocked by policy")
  if (res.decision === "ask") {
    if (await askUser(res.reason || "agent-ledger: needs approval")) return
    throw new Error(`${res.reason || "agent-ledger"} - this needs human approval and was not approved, so it was not run.`)
  }
}

export default {
  id: "agent-ledger",

  // ---------------------------------------------------------------- OpenCode V1 (1.x)
  async server({ directory, worktree }) {
    const base = { agent: "opencode", directory, worktree }
    const failed = new Set()
    return {
      "tool.execute.before": async (input, output) => {
        await gate({ ...base, phase: "tool.before", tool: input.tool, sessionID: input.sessionID,
                     callID: input.callID, args: output.args }, async () => false)
      },
      "tool.execute.after": async (input, output) => {
        await record({ ...base, phase: "tool.after", tool: input.tool, sessionID: input.sessionID, callID: input.callID,
                       args: input.args, output: { title: output?.title, output: output?.output, metadata: output?.metadata } })
      },
      "chat.message": async (input, output) => {
        const text = (output?.parts || []).filter((p) => p && p.type === "text").map((p) => p.text).join("\n")
        await record({ ...base, phase: "chat.message", sessionID: input.sessionID, prompt: text })
      },
      event: async ({ event }) => {
        const p = event?.properties || {}
        if (["session.created", "session.idle", "session.deleted", "session.error"].includes(event?.type)) {
          await record({ ...base, phase: "event", event_type: event.type, sessionID: p.sessionID || p.info?.id,
                         error: p.error ? String(p.error?.message || p.error?.name || p.error) : undefined })
        } else if (event?.type === "message.part.updated") {
          // tool.execute.after does not fire for failed tools in V1, so failures come from part updates
          const part = p.part
          if (part?.type === "tool" && part.state?.status === "error" && !failed.has(part.callID)) {
            failed.add(part.callID)
            await record({ ...base, phase: "tool.error", tool: part.tool, sessionID: part.sessionID || p.sessionID,
                           callID: part.callID, args: part.state.input, error: part.state.error })
          }
        }
      },
    }
  },

  // ---------------------------------------------------------------- OpenCode V2 (2.x)
  async setup(ctx) {
    const base = { agent: "opencode", directory: ctx.location?.directory,
                   worktree: ctx.location?.project?.directory || ctx.location?.directory }

    // permission.assert first applies the agent's own rules, and OpenCode's default agent allows
    // everything, which would approve our "ask" silently. Force our own requests to "ask" so a person
    // really decides (headless runs auto-decline; only an explicit --auto approves). A config "deny"
    // stays final. This hook must never throw.
    if (ctx.permission?.hook) {
      await ctx.permission.hook("evaluate", (e) => {
        try {
          if (e?.action === "agent-ledger" && e.effect !== "deny") e.effect = "ask"
        } catch {
          // never break permission evaluation
        }
      })
    }

    await ctx.tool.hook("execute.before", async (e) => {
      await gate({ ...base, phase: "tool.before", tool: e.tool, sessionID: e.sessionID, callID: e.id, args: e.input },
        async (reason) => {
          try {
            await ctx.permission.assert({
              sessionID: e.sessionID, agent: e.agent, action: "agent-ledger",
              resources: [`${e.tool}: ${reason}`], source: { type: "tool", messageID: e.messageID, id: e.id },
            })
            return true
          } catch {
            return false
          }
        })
    })

    // V2 runs this for successes and failures; it must never throw (a throw here crashes the call)
    await ctx.tool.hook("execute.after", async (e) => {
      try {
        const failedCall = e.status === "error"
        await record({ ...base, phase: failedCall ? "tool.error" : "tool.after", tool: e.tool, sessionID: e.sessionID,
                       callID: e.id, args: e.input, error: failedCall ? String(e.error?.message || e.error) : undefined,
                       output: failedCall ? undefined : { output: e.result?.output, metadata: e.result?.metadata } })
      } catch {
        // never break the session
      }
    })

    if (ctx.session?.hook) {
      await ctx.session.hook("prompt", async (e) => {
        try {
          await record({ ...base, phase: "chat.message", sessionID: e.sessionID, prompt: e.prompt?.text || "" })
        } catch {
          // never break the session
        }
      })
    }

    // Session lifecycle. setup() is awaited before the plugin is active, so this loop is not awaited.
    const lifecycle = { "session.created": "session.created", "session.deleted": "session.deleted",
                        "session.execution.succeeded": "session.idle", "session.execution.failed": "session.error" }
    if (ctx.event?.subscribe) {
      ;(async () => {
        try {
          for await (const ev of ctx.event.subscribe({ types: Object.keys(lifecycle) })) {
            const kind = lifecycle[ev?.type]
            if (kind) {
              await record({ ...base, phase: "event", event_type: kind, sessionID: ev.sessionID || ev.properties?.sessionID,
                             error: ev.error ? String(ev.error?.message || ev.error) : undefined })
            }
          }
        } catch {
          // event stream ended or is unavailable: tool calls are still gated
        }
      })()
    }
  },
}
